from __future__ import annotations

from ..release import ReleaseContext


def release_gates_markdown(context: ReleaseContext) -> str:
    gates = context.gates
    baseline = context.installed_baseline
    satisfied = sum(gate.status == "software-satisfied" for gate in gates)
    lines = [
        "# Release Gates",
        "",
        "> Generated by `./hfx generate`. Do not edit manually.",
        "",
        f"Software-satisfied gates: `{satisfied}` of `{len(gates)}`.",
        "A software-satisfied gate is not a release, hardware qualification, or publication decision.",
        "",
        "## Target And Behavioral Baseline",
        "",
        f"Target: `{context.target.product_version}-{context.target.package_release}` "
        f"(`{context.target.state}`).",
        f"Private behavioral reference: `{baseline.id}` (`{baseline.package_version}`).",
        "",
        "| State | Value |",
        "| --- | --- |",
        f"| `artifact_frozen` | `{str(baseline.artifact_frozen).lower()}` |",
        f"| `installed_verified` | `{str(baseline.installed_verified).lower()}` |",
        f"| `behavioral_baseline_accepted` | `{str(baseline.behavioral_baseline_accepted).lower()}` |",
        f"| `public_release_authorized` | `{str(baseline.public_release_authorized).lower()}` |",
        "",
        "The accepted baseline constrains reconstruction behavior; it does not authorize or qualify the target artifacts.",
        "",
        "| Gate | Status | Physical evidence | Publication decision |",
        "| --- | --- | --- | --- |",
    ]
    for gate in gates:
        lines.append(
            f"| `{gate.id}` {gate.title} | `{gate.status}` | "
            f"{'required' if gate.physical_evidence_required else 'no'} | "
            f"{'required' if gate.publication_authorization_required else 'no'} |"
        )
    lines.extend(["", "## Criteria And Remaining Work", ""])
    for gate in gates:
        lines.extend([f"### {gate.id}: {gate.title}", "", "Criteria:", ""])
        lines.extend(f"- {item}" for item in gate.criteria)
        lines.extend(["", "Evidence:", ""])
        lines.extend(f"- [`{path}`](../../{path})" for path in gate.evidence)
        lines.extend(["", "Remaining:", ""])
        if gate.remaining:
            lines.extend(f"- {item}" for item in gate.remaining)
        else:
            lines.append("- No remaining work inside this gate's defined software scope.")
        lines.append("")
    return "\n".join(lines)
